begin;
select plan(25);
insert into organizations (id,name) values ('f5000000-0000-0000-0000-000000000001','Atomic org');
insert into auth.users (id,email) values ('f5000000-0000-0000-0000-000000000002','atomic@example.test');
insert into profiles (id,org_id,full_name,email,role) values ('f5000000-0000-0000-0000-000000000002','f5000000-0000-0000-0000-000000000001','Atomic','atomic@example.test','Engineer');
insert into organizations (id,name) values ('f5000000-0000-0000-0000-000000000101','Other org');
insert into auth.users (id,email) values ('f5000000-0000-0000-0000-000000000102','other-atomic@example.test'), ('f5000000-0000-0000-0000-000000000103','other-engineer@example.test');
insert into profiles (id,org_id,full_name,email,role) values
 ('f5000000-0000-0000-0000-000000000102','f5000000-0000-0000-0000-000000000101','Other','other-atomic@example.test','Project Manager'),
 ('f5000000-0000-0000-0000-000000000103','f5000000-0000-0000-0000-000000000001','Other Engineer','other-engineer@example.test','Engineer');
insert into companies (id,org_id,name,type) values ('f5000000-0000-0000-0000-000000000104','f5000000-0000-0000-0000-000000000101','Other supplier','Vendor');
insert into auth.users (id,email) values ('f5000000-0000-0000-0000-000000000105','disabled-atomic@example.test');
insert into profiles (id,org_id,full_name,email,role,status) values ('f5000000-0000-0000-0000-000000000105','f5000000-0000-0000-0000-000000000001','Disabled','disabled-atomic@example.test','Engineer','disabled');
insert into procurements (id,org_id,title,requested_by_id) values ('f5000000-0000-0000-0000-000000000060','f5000000-0000-0000-0000-000000000001','Legacy','f5000000-0000-0000-0000-000000000002');
insert into procurement_items (id,org_id,procurement_id,name,quantity,rate) values ('f5000000-0000-0000-0000-000000000061','f5000000-0000-0000-0000-000000000001','f5000000-0000-0000-0000-000000000060','Existing',1,5);
set local role authenticated;
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000002","role":"authenticated"}';
select lives_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Draft","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.25,"description":null}]')$$, 'requester creates header and line');
select is((select count(*) from public.procurement_items where procurement_id='f5000000-0000-0000-0000-000000000010'),1::bigint,'one line created');
select is((select amount from public.procurement_items where id='f5000000-0000-0000-0000-000000000011'),2.50::numeric,'exact line amount');
select lives_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Draft","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.25,"description":null}]')$$, 'same request retries');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Changed","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.25,"description":null}]')$$,'23505',null,'changed header conflicts');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Draft","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.26,"description":null}]')$$,'23505',null,'changed line conflicts');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000020', '{"title":"Rollback","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000021","name":"Valid","quantity":1,"rate":1},{"id":"f5000000-0000-0000-0000-000000000011","name":"Collision","quantity":1,"rate":1}]')$$,'23505',null,'line collision aborts transaction');
select is((select count(*) from public.procurements where id='f5000000-0000-0000-0000-000000000020'),0::bigint,'failed transaction leaves no header');
select is((select count(*) from public.procurement_items where id='f5000000-0000-0000-0000-000000000021'),0::bigint,'failed transaction leaves no line');
select lives_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000030', '{"title":"Empty","project_id":null,"vendor_id":null}', '[]')$$, 'empty draft created');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000030', '{"title":"Empty","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000031","name":"Added","quantity":1,"rate":1}]')$$,'23505',null,'same request id with additional line conflicts');
select is((select requested_by_id from public.procurements where id='f5000000-0000-0000-0000-000000000010'),'f5000000-0000-0000-0000-000000000002'::uuid,'requester derived from caller');
select is((select status::text from public.procurements where id='f5000000-0000-0000-0000-000000000010'),'Draft','request remains Draft');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000040', '{"title":"Invalid","project_id":null,"vendor_id":null,"status":"Approved"}', '[]')$$,'22023',null,'cannot choose approval state');
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000102","role":"authenticated"}';
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Draft","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.25,"description":null}]')$$,'23505',null,'cross-org retry denied');
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000103","role":"authenticated"}';
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000010', '{"title":"Draft","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000011","name":"Item","quantity":2,"rate":1.25,"description":null}]')$$,'23505',null,'other requester cannot adopt ID');
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000050', '{"title":"Cross org","project_id":null,"vendor_id":"f5000000-0000-0000-0000-000000000104"}', '[]')$$,'42501',null,'foreign supplier denied');
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000105","role":"authenticated"}';
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000051', '{"title":"Disabled","project_id":null,"vendor_id":null}', '[]')$$,'42501',null,'disabled requester denied');
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000052', '{"title":"Spoof","project_id":null,"vendor_id":null,"requested_by_id":"f5000000-0000-0000-0000-000000000002"}', '[]')$$,'42501',null,'disabled requester cannot spoof identity');
reset role;
select ok(not has_function_privilege('anon','public.create_procurement_with_items(uuid,jsonb,jsonb)','EXECUTE'),'anonymous role cannot execute');
select ok(not has_table_privilege('authenticated','public.procurement_create_intents','SELECT'),'intent contents not exposed directly');
set local role authenticated;
set local request.jwt.claims = '{"sub":"f5000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000060', '{"title":"Legacy","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000061","name":"Different","quantity":1,"rate":5}]')$$,'23505',null,'legacy mismatch rejected');
select lives_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000060', '{"title":"Legacy","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000061","name":"Existing","quantity":1,"rate":5},{"id":"f5000000-0000-0000-0000-000000000062","name":"Missing","quantity":2,"rate":6}]')$$,'matching legacy partial draft reconciles');
select is((select count(*) from public.procurement_items where procurement_id='f5000000-0000-0000-0000-000000000060'),2::bigint,'legacy reconciliation keeps existing and adds missing line');
select lives_ok($$select public.create_procurement_with_items('f5000000-0000-0000-0000-000000000060', '{"title":"Legacy","project_id":null,"vendor_id":null}', '[{"id":"f5000000-0000-0000-0000-000000000061","name":"Existing","quantity":1,"rate":5},{"id":"f5000000-0000-0000-0000-000000000062","name":"Missing","quantity":2,"rate":6}]')$$,'legacy reconciliation retry is idempotent');
select * from finish();
rollback;
